package dev.manik.xraymirror.gl

import android.content.Context
import dev.manik.xraymirror.Layer
import org.json.JSONArray

class FactEntry(val layer: Layer, val title: String, val match: Regex, val fact: String, val anchor: String?)

/** Curated titles + one-line facts (assets/facts.json, generated by tools/facts.py). */
class Facts(context: Context, data: AnatomyData) {
    val entries: List<FactEntry>
    private val byPart = HashMap<Int, FactEntry>()
    /** Label entries resolved to their anchor part, in priority order. */
    val labels: List<Pair<FactEntry, Part>>

    init {
        val arr = JSONArray(context.assets.open("facts.json").bufferedReader().use { it.readText() })
        entries = (0 until arr.length()).map {
            val o = arr.getJSONObject(it)
            FactEntry(Layer.valueOf(o.getString("layer").uppercase()), o.getString("title"),
                Regex(o.getString("match"), RegexOption.IGNORE_CASE), o.getString("fact"),
                if (o.has("anchor")) o.getString("anchor") else null)
        }
        for (p in data.parts) entries.firstOrNull { it.layer == p.layer && it.match.containsMatchIn(p.name) }?.let { byPart[p.id] = it }
        val byName = data.parts.associateBy { it.name }
        labels = entries.mapNotNull { e -> e.anchor?.let { byName[it] }?.let { e to it } }
    }

    fun forPart(id: Int): FactEntry? = byPart[id]
}
